  #status { padding: 4px 10px; font-size: 11px; color: #6a7a8a; background: #111820; border-top: 1px solid #1e2a38; display: flex; justify-content: space-between; }
  .modal { position: fixed; inset: 0; background: rgba(0,0,0,0.85); display: none; align-items: center; justify-content: center; z-index: 100; padding: 12px; }
  .modal.active { display: flex; }
  .modal-content { background: #111820; border: 1px solid #2a3a4d; border-radius: 12px; padding: 16px; width: 100%; max-width: 480px; max-height: 92vh; overflow-y: auto; }
  .modal-content h2 { font-size: 16px; margin-bottom: 12px; color: #4dd0e1; }
  .modal-content label { display: block; font-size: 12px; color: #8a9aaa; margin-top: 10px; }
  .modal-content input, .modal-content select, .modal-content textarea { width: 100%; background: #0a0e14; border: 1px solid #2a3a4d; color: #e6e6e6; padding: 10px; border-radius: 6px; }
  .field-row { display: flex; gap: 8px; } .field-row > div { flex: 1; }
  .modal-actions { display: flex; gap: 8px; margin-top: 16px; }
  .modal-actions button { flex: 1; padding: 10px; border-radius: 6px; border: none; cursor: pointer; }
  .save { background: #0d6e4f; color: white; } .cancel { background: #2a3a4d; color: #e6e6e6; } .delete { background: #8b1e1e; color: white; }
  .tabs { display: flex; gap: 4px; margin-bottom: 12px; border-bottom: 1px solid #1e2a38; overflow-x: auto; }
  .tabs button { background: none; border: none; color: #6a7a8a; padding: 8px 12px; cursor: pointer; white-space: nowrap; }
  .tabs button.active { color: #4dd0e1; border-bottom: 2px solid #4dd0e1; }
  .tab-content { display: none; } .tab-content.active { display: block; }
  .toggle-row { display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid #1e2a38; }
  #tunnelBox { display: none; background: #0a0e14; padding: 10px; word-break: break-all; color: #4dd0e1; margin-bottom: 10px; }
</style>
</head>
<body>
<div id="app">
  <div id="topbar">
    <button id="btnAddEntity" onclick="openAddEntity()" class="primary disabled">+ كيان</button>
    <button id="btnAddRelation" onclick="openAddRelation()" class="disabled">+ علاقة</button>
    <button onclick="runLayout()">تخطيط</button>
    <button id="btnSettings" onclick="openSettings()" style="display:none;">⚙️</button>
    <button onclick="logout()" class="danger">🚪 خروج</button>
    <span class="brand">database osint</span>
  </div>
  <div id="cy"></div>
  <div id="status"><span id="statusText">0 | 0</span><span id="statusMsg">جاهز</span></div>
</div>

<div class="modal" id="settingsModal">
  <div class="modal-content">
    <h2>⚙️ لوحة التحكم</h2>
    <label>كلمة سر الزائر</label><input type="text" id="cfg_guest_pass">
    <div class="toggle-row"><span>السماح للزائر بالإضافة</span><input type="checkbox" id="cfg_edit"></div>
    <div class="toggle-row"><span>السماح برؤية كلمات المرور</span><input type="checkbox" id="cfg_secrets"></div>
    <div class="toggle-row"><span>درع الخصوصية (منع لقطة الشاشة)</span><input type="checkbox" id="cfg_shield"></div>
    <hr style="margin: 15px 0; border-color: #1e2a38;">
    <h2>🌐 الإنترنت (اختياري)</h2>
    <div id="tunnelBox"></div>
    <button id="btnTunnel" onclick="toggleTunnel()" style="background:#0d6e4f;color:white;border:none;padding:10px;width:100%;cursor:pointer;">🔗 توليد رابط إنترنت</button>
    <div class="modal-actions"><button class="cancel" onclick="closeModal('settingsModal')">إغلاق</button><button class="save" onclick="saveSettings()">حفظ</button></div>
  </div>
</div>

<div class="modal" id="entityModal">
  <div class="modal-content">
    <h2 id="entityModalTitle">إضافة كيان</h2>
    <div class="tabs">
      <button class="active" onclick="switchTab(event,'basic')">أساسي</button>
