<script>
let cy; let localData = { entities: [], relations: [] }; let localConfig = {}; let isAdmin = false; let canEdit = false;
let editingEntityId = null, currentEntityId = null, editingRelationId = null, currentAvatar = null, currentImages = [];
const TYPE_COLORS = { person: '#4dd0e1', email: '#ff8a65', phone: '#ba68c8', username: '#ffd54f', domain: '#81c784', ip: '#e57373', org: '#64b5f6', location: '#a1887f', other: '#90a4ae' };

document.addEventListener('visibilitychange', () => { if (!isAdmin && localConfig.shield_enabled) document.getElementById('app').style.display = document.hidden ? 'none' : 'flex'; });

async function init() {
  try {
    const authRes = await fetch('/check_auth?t=' + Date.now(), { cache: 'no-store' }); const authData = await authRes.json();
    isAdmin = authData.admin; localConfig = authData.config; canEdit = isAdmin || localConfig.guest_can_edit;
    if (isAdmin) document.getElementById('btnSettings').style.display = 'block';
    if (canEdit) { document.getElementById('btnAddEntity').classList.remove('disabled'); document.getElementById('btnAddRelation').classList.remove('disabled'); }
  } catch(e) {}
  await fetchData(); initCy(); loadGraph();
  setInterval(async () => { await fetchData(); loadGraph(); }, 3000);
}
async function fetchData() { try { const res = await fetch('/data?t=' + Date.now(), { cache: 'no-store' }); localData = await res.json(); } catch(e) {} }

function initCy() {
  cy = cytoscape({ container: document.getElementById('cy'),
    style: [
      { selector: 'node', style: { 'background-color': ele => TYPE_COLORS[ele.data('type')] || TYPE_COLORS.other, 'label': 'data(label)', 'color': '#fff', 'font-size': '11px', 'text-valign': 'bottom', 'text-outline-color': '#000', 'text-outline-width': 2 } },
      { selector: 'edge', style: { 'width': 1.5, 'line-color': '#2a3a4d', 'target-arrow-color': '#2a3a4d', 'target-arrow-shape': 'triangle', 'curve-style': 'bezier', 'label': 'data(label)', 'font-size': '9px', 'color': '#6a7a8a' } }
    ], layout: { name: 'cose', animate: false }
  });
  cy.on('tap', 'node', e => showNodeInfo(e.target.id()));
  cy.on('tap', 'edge', e => { if (canEdit) openEditRelation(e.target.id()); });
}

function loadGraph() {
  if (JSON.stringify(cy.nodes().map(n => n.data())) !== JSON.stringify(localData.entities) || JSON.stringify(cy.edges().map(e => e.data())) !== JSON.stringify(localData.relations)) {
    cy.elements().remove();
    localData.entities.forEach(e => cy.add({ data: { id: e.id, label: e.name || 'بدون اسم', type: e.type || 'other' } }));
    localData.relations.forEach(r => { if (cy.getElementById(r.from).length && cy.getElementById(r.to).length) cy.add({ data: { id: r.id, source: r.from, target: r.to, label: r.type } }); });
    if (cy.nodes().length > 0) cy.layout({ name: 'cose', animate: true }).run();
    document.getElementById('statusText').textContent = `الكيانات: ${cy.nodes().length} | العلاقات: ${cy.edges().length}`;
  }
}

async function saveData() { if (!canEdit) return; try { await fetch('/save', { method: 'POST', body: JSON.stringify(localData) }); setMsg('✅ تم الحفظ'); } catch(e) { setMsg('❌ خطأ'); } }
function runLayout() { cy.layout({ name: 'cose', animate: true }).run(); }
function setMsg(m) { document.getElementById('statusMsg').textContent = m; setTimeout(() => document.getElementById('statusMsg').textContent = 'جاهز', 2000); }
function switchTab(evt, name) { document.querySelectorAll('.tabs button').forEach(b => b.classList.remove('active')); document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active')); evt.target.classList.add('active'); document.getElementById('tab-' + name).classList.add('active'); }
function closeModal(id) { document.getElementById(id).classList.remove('active'); }
async function logout() { await fetch('/logout'); window.location.href = '/?t=' + Date.now(); }

async function openSettings() {
  document.getElementById('cfg_guest_pass').value = localConfig.guest_pass || '0000';
  document.getElementById('cfg_edit').checked = localConfig.guest_can_edit; document.getElementById('cfg_secrets').checked = localConfig.guest_can_see_secrets; document.getElementById('cfg_shield').checked = localConfig.shield_enabled;
  document.getElementById('settingsModal').classList.add('active');
  const tData = await (await fetch('/tunnel_status?t=' + Date.now())).json();
  const box = document.getElementById('tunnelBox'); const btn = document.getElementById('btnTunnel');
  if (tData.url) { box.style.display='block'; box.innerHTML = tData.url; btn.textContent = '🛑 إيقاف'; btn.style.background = '#8b1e1e'; } else { box.style.display='none'; btn.textContent = '🔗 توليد رابط'; btn.style.background = '#0d6e4f'; }
}
async function saveSettings() {
  const newCfg = { guest_pass: document.getElementById('cfg_guest_pass').value, guest_can_edit: document.getElementById('cfg_edit').checked, guest_can_see_secrets: document.getElementById('cfg_secrets').checked, shield_enabled: document.getElementById('cfg_shield').checked };
  await fetch('/config', { method: 'POST', body: JSON.stringify(newCfg) }); localConfig = newCfg; closeModal('settingsModal');
}
async function toggleTunnel() {
  const btn = document.getElementById('btnTunnel'); const box = document.getElementById('tunnelBox');
  if (btn.textContent.includes('إيقاف')) { await fetch('/stop_tunnel'); setTimeout(()=>location.reload(), 1000); }
  else { btn.textContent = 'جاري التوليد...'; await fetch('/start_tunnel'); const int = setInterval(async () => { const d = await (await fetch('/tunnel_status')).json(); if (d.url) { clearInterval(int); box.style.display='block'; box.innerHTML=d.url; btn.textContent='🛑 إيقاف'; btn.style.background='#8b1e1e'; } }, 2000); }
}

function openAddEntity() {
  editingEntityId = null; document.getElementById('entityModalTitle').textContent = 'إضافة كيان';
  ['name','alias','age','nationality','email','phone','whatsapp','telegram','facebook','instagram','twitter','address','gps','passwords','sensitive','notes','tags'].forEach(f => document.getElementById('f_' + f).value = '');
  document.getElementById('entityDeleteBtn').style.display = 'none'; document.getElementById('entityModal').classList.add('active');
}
async function saveEntity() {
  const data = { id: editingEntityId || ('e_' + Date.now()), name: document.getElementById('f_name').value || 'بدون اسم', alias: document.getElementById('f_alias').value, type: document.getElementById('f_type').value, age: document.getElementById('f_age').value, nationality: document.getElementById('f_nationality').value, email: document.getElementById('f_email').value, phone: document.getElementById('f_phone').value, whatsapp: document.getElementById('f_whatsapp').value, telegram: document.getElementById('f_telegram').value, facebook: document.getElementById('f_facebook').value, instagram: document.getElementById('f_instagram').value, twitter: document.getElementById('f_twitter').value, address: document.getElementById('f_address').value, gps: document.getElementById('f_gps').value, passwords: document.getElementById('f_passwords').value, sensitive: document.getElementById('f_sensitive').value, notes: document.getElementById('f_notes').value, tags: document.getElementById('f_tags').value };
  const idx = localData.entities.findIndex(e => e.id === data.id); if (idx >= 0) localData.entities[idx] = data; else localData.entities.push(data);
  await saveData(); closeModal('entityModal');
}
async function showNodeInfo(id) {
  currentEntityId = id; const d = localData.entities.find(e => e.id === id); if(!d) return;
  let html = `<h3 style="color:#4dd0e1">${d.name}</h3>`;
  if(d.alias) html += `<p>الكنية: ${d.alias}</p>`; if(d.age) html += `<p>العمر: ${d.age}</p>`; if(d.phone) html += `<p>الهاتف: ${d.phone}</p>`;
  if (isAdmin || localConfig.guest_can_see_secrets) { if(d.passwords) html += `<p style="color:red">كلمات المرور: ${d.passwords}</p>`; }
  if(d.notes) html += `<p>ملاحظات: ${d.notes}</p>`;
  document.getElementById('infoTitle').textContent = d.name; document.getElementById('infoBody').innerHTML = html;
  document.getElementById('infoEditBtn').style.display = canEdit ? 'block' : 'none'; document.getElementById('infoModal').classList.add('active');
}
async function editCurrentEntity() {
  const d = localData.entities.find(e => e.id === currentEntityId); editingEntityId = currentEntityId;
  document.getElementById('entityModalTitle').textContent = 'تعديل كيان';
  ['name','alias','age','nationality','email','phone','whatsapp','telegram','facebook','instagram','twitter','address','gps','passwords','sensitive','notes','tags'].forEach(f => document.getElementById('f_' + f).value = d[f] || '');
  document.getElementById('f_type').value = d.type || 'person'; document.getElementById('entityDeleteBtn').style.display = 'block'; closeModal('infoModal'); document.getElementById('entityModal').classList.add('active');
}
async function deleteCurrentEntity() { localData.entities = localData.entities.filter(e => e.id !== editingEntityId); localData.relations = localData.relations.filter(r => r.from !== editingEntityId && r.to !== editingEntityId); await saveData(); closeModal('entityModal'); }
function openAddRelation() {
  const nodes = cy.nodes(); if (nodes.length < 2) return;
  const f = document.getElementById('relFrom'), t = document.getElementById('relTo'); f.innerHTML = ''; t.innerHTML = '';
  nodes.forEach(n => { f.add(new Option(n.data('label'), n.id())); t.add(new Option(n.data('label'), n.id())); }); document.getElementById('relationModal').classList.add('active');
}
async function saveRelation() {
  const f = document.getElementById('relFrom').value, t = document.getElementById('relTo').value, type = document.getElementById('relType').value || 'مرتبط';
  if(f===t) return; localData.relations.push({ id: 'r_' + Date.now(), from: f, target: t, type: type }); await saveData(); closeModal('relationModal');
}
init();
</script>
</body>
</html>
EOF
echo "✅ index.html ready"
